
WITH r AS MATERIALIZED (SELECT * FROM recommendation_request WHERE surface_version='watch-for-you-v1' AND created_at>='2026-09-08T01:45:00Z' AND created_at<'2026-09-15T01:45:00Z'), x AS (SELECT r.id,r.created_at,r.retrieval_latency_ms,count(i.id) cards,count(i.id) FILTER(WHERE i.candidate_generator='multi-interest-profile') profile_cards FROM r LEFT JOIN recommendation_served_item i ON i.request_id=r.id GROUP BY 1,2,3)
SELECT profile_cards,count(*) requests,sum(cards) cards,min(created_at) first_request,max(created_at) latest_request,percentile_cont(0.5) within group(order by retrieval_latency_ms) latency_p50_ms,percentile_cont(0.95) within group(order by retrieval_latency_ms) latency_p95_ms FROM x GROUP BY 1 ORDER BY 1;
SELECT DISTINCT k key FROM recommendation_served_item i JOIN recommendation_request r ON r.id=i.request_id CROSS JOIN LATERAL jsonb_object_keys(i.candidate_provenance) k WHERE r.surface_version='watch-for-you-v1' AND r.created_at>='2026-09-08T01:45:00Z' AND r.created_at<'2026-09-15T01:45:00Z' ORDER BY 1;
